/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin fn_init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.setTime('6M', 'fromData', 'toData');
    const scode = "null";
    const sValue = "null";
    const sName = "null";
    if (scode !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('disclosureType', sName);
        const dName = document.getElementsByName("disclosureTypeArr" + scode);
        const len1 = dName.length;
        const svs = sValue.split("|");
        for (let i = 0; i < dName.length; i++) {
            for (let j = 0; j < svs.length; j++) {
                if (dName[i].value === svs[j]) {
                    dName[i].checked = true;
                    if (sName !== "" && sName === "6") {
                        (document.frm || { elements: [] }).reportNm.value = "신규상장";
                    }
                    await scwin.fncSearch();
                }
            }
        }
    }
    await scwin.fnSearchCorpName();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosure_type
 * @author Inswave
 * @date 2026. 09. 29
 * @param code
 * @returns
 * @hidden N
*/
scwin.disclosure_type = function (code) {
    /* sdd-asis-lifecycle:begin disclosure_type — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const layer = $c.util.getComponent("layer" + code);
    const img = $c.util.getComponent("dTypeImg" + code);
    if (img.getValue() === "on") {
        img.src = "/img/btn/btn_" + code + ".gif";
        img.setValue("off");
    } else {
        img.src = "/img/btn/btn_" + code + "_on.gif";
        img.setValue("on");
    }
    if (img.getValue() === "on") {
        layer.style.display = 'inline';
    } else {
        if (img.getValue() === "off") {
            layer.style.display = 'none';
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosure_window_check
 * @author Inswave
 * @date 2026. 09. 29
 * @param code val
 * @returns
 * @hidden N
*/
scwin.disclosure_window_check = function (code, val) {
    /* sdd-asis-lifecycle:begin disclosure_window_check — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const dName = document.getElementsByName("disclosureTypeArr" + code);
    let bl = true;
    if (val === "unCheck") {
        bl = false;
    }
    scwin.checkedBox(dName, bl);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkedBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param dName yn
 * @returns
 * @hidden N
*/
scwin.checkedBox = function (dName, yn) {
    /* sdd-asis-lifecycle:begin checkedBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (dName.length == null) {
        dName.checked = yn;
    } else {
        for (let j = 0; j < dName.length; j++) {
            dName[j].checked = yn;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.order
 * @author Inswave
 * @date 2026. 09. 29
 * @param startVal
 * @returns
