*/
scwin.order = async function (startVal) {
    /* sdd-asis-lifecycle:begin order — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (startVal === "ok") {
        await scwin.fnSearchCorpName();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = ($c.util.fieldEl('AKCKwd', 'searchCorpName'));
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            chkValidChar(obj);
            scwin.corpType(obj);
            await scwin.fnSearchCorpName();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.corpType
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.corpType = function (val) {
    /* sdd-asis-lifecycle:begin corpType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.num.isNumber(val.value) === true) {
        if (val.value.length < 6 || val.value.length > 7) {
            val.value = "";
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
            return false;
        } else {
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "number");
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "char");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosureAllSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.disclosureAllSetting = function () {
    /* sdd-asis-lifecycle:begin disclosureAllSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const len = scwin.discloureArr.length;
    for (let x = 0; x < len; x++) {
        scwin.disclosureSetting(scwin.discloureArr[x]);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosureSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param code
 * @returns
 * @hidden N
*/
scwin.disclosureSetting = function (code) {
    /* sdd-asis-lifecycle:begin disclosureSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const get_name = document.getElementsByName("disclosureTypeArr" + code);
    const set_name = (document.frm || { elements: [] }).elements["disclosureType"+code];
    const length = get_name.length;
    let check_setting = "";
    if (length == null) {
        if (get_name.checked === true) {
            check_setting += get_name.value + "|";
        }
    } else {
        for (let j = 0; j < length; j++) {
            if (get_name[j].checked === true) {
                check_setting += get_name[j].value + "|";
            }
        }
    }
    set_name.value = check_setting;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.frm || { elements: [] });
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchCorpNameExt");
        scwin.form_frm.target = "iframe_1";
        await scwin.tx_fnSearchCorpName();
    } else {
        await scwin.fncSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param repIsuSrtCd
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (repIsuSrtCd) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.frm || { elements: [] });
    if (repIsuSrtCd === "") {
        if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "char") {
            await $c.win.alert("조회한 종목명이 존재하지 않습니다.");
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
            return;
        } else {
            if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "number") {
                await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
                $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
                return;
            }
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', repIsuSrtCd);
        await scwin.fncSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setReportNameInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formNm
