*/
scwin.setReportNameInfo = function (formCd, formNm) {
    /* sdd-asis-lifecycle:begin setReportNameInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.frm || { elements: [] }).reportNm.value = formNm;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fncSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fncSearch = async function () {
    /* sdd-asis-lifecycle:begin fncSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.disclosureAllSetting();
    const frm = (document.frm || { elements: [] });
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "details_discls_mktact_sub_ext");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchDetailsDisclsMktactSubExt");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", "1");
    scwin.form_frm.target = "iframe";
    openWaitDiv(440, 445);
    await scwin.tx_fncSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.disclosureAllSetting();
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('allRepIsuSrtCd', "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "details_discls_mktact_sub_ext");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchDetailsDisclsMktactSubExt");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validation = function () {
    /* sdd-asis-lifecycle:begin validation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.frm || { elements: [] });
    let returnValue = false;
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        returnValue = true;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('allRepIsuSrtCd') !== "") {
        returnValue = true;
    }
    if (f.submitOblgNm.value !== "") {
        returnValue = true;
    }
    if (f.reportNm.value !== "") {
        returnValue = true;
    }
    const len = scwin.discloureArr.length;
    for (let x = 0; x < len; x++) {
        const dt = $c.util.getComponent("disclosureType" + scwin.discloureArr[x]);
        if (dt.getValue() !== "") {
            returnValue = true;
        }
    }
    return returnValue;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.crossCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param val obj
 * @returns
 * @hidden N
*/
scwin.crossCheck = async function (val, obj) {
    /* sdd-asis-lifecycle:begin crossCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.frm || { elements: [] });
    if (val === "1") {
        if (obj.value !== "") {
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('oldSearchCorpName', obj.value);
        }
    } else {
        if (val === "2") {
            if (obj.value !== "") {
                if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
                    await $c.win.alert("해당항목 선택시 법인명이 초기화 됩니다.");
                }
                $c.util.getComponent("AKCKwd").setValue("");
            } else {
                $c.util.getComponent("AKCKwd").setValue($c.util.getComponent('dma_fnSearchCorpNameReq').get('oldSearchCorpName'));
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


